/**
 * InsForge Edge: full profile embed SVG.
 *
 * Returns a 600×180 profile card (dark/light themes) suitable for embedding
 * in tweets, Notion pages, GitHub READMEs, personal sites — anywhere an SVG
 * <img> tag works. Self-contained: no external font dependencies, no fetched
 * avatar.
 *
 * Usage:
 *   <img src="https://<insforge>/functions/tokentracker-embed-svg?user_id=<uuid>" />
 *
 * Query params:
 *   user_id  (required) UUID
 *   theme    light | dark             (default: light)
 *   period   week | month | total       (default: total)
 * Privacy: gates on `is_public=true` (the same opt-in that the leaderboard
 * profile endpoint enforces). Private profiles → "private" placeholder SVG.
 *
 * Caching: 60s ISR via Cache-Control.
 */
import { createClient } from "npm:@insforge/sdk";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// Blocked users must disappear from EVERY public read path, not only the
// leaderboard list/profile endpoints — stale snapshot rows would otherwise
// keep serving their embed card after a ban.
const BLOCKED_LEADERBOARD_USER_IDS = new Set(
  (Deno.env.get("LEADERBOARD_BLOCKED_USER_IDS") ?? "")
    .split(",")
    .map((id) => id.trim().toLowerCase())
    .filter(Boolean),
);

// The embed card mirrors the landing page's deep-space violet theme
// (dashboard/src/ui/marketing/v3/palette.js is the reference): near-black
// void, white type, and a single violet accent carrying the glow. Values are
// inlined here because the SVG must stay self-contained — GitHub re-serves it
// through camo, which cannot resolve anything outside the document.
const PALETTE = {
  light: {
    // The light card gets its depth from shading the surface itself rather
    // than from a drop-shadow filter: filters rasterize poorly through
    // GitHub's camo proxy, and a shadow has nowhere to fall when the badge
    // sits on a white README anyway.
    //
    // The trick that makes it read as a *lit* surface instead of a tinted
    // sheet is having a light source. `bgTop` is near-white at the top and
    // `bgBottom` is a deep violet at the bottom, and a white radial sheen
    // pinned to the top-left corner sits over both. Lit corner, shaded
    // corner — that diagonal is what gives the card form. Before this the
    // gradient ran evenly top-to-bottom and the whole thing read flat no
    // matter how far the two stops were pushed apart.
    bgTop: "#fdfcff",
    bgBottom: "#e6e0f7",
    cardBorder: "#d8d0f2",
    fg: "#0b0b12",
    secondary: "#3a3a48",
    muted: "#63637a",
    faint: "#8f8fa6",
    // Provider percentages: brighter than the panel heading (muted) but a step
    // below the provider labels (secondary), so the figure column reads as data
    // rather than decoration without competing with the names. The "whiteness"
    // ladder mirrors the dark card's: this is the darker-ink side of it.
    pctInk: "#4a4a60",
    accent: "#6d55f0",
    accentSoft: "#8a7aff",
    // The star specks were #fbdfff at 0.5 opacity — near-white pink on a white
    // card, which is invisible. On the light surface they need to be a tint
    // DARKER than the background to read at all.
    divider: "#dbd4f0",
    glowOpacity: 0.18,
    // White specular highlight in the top-left corner. Zero on the dark theme:
    // that card is meant to read as deep space lit from within by the accent
    // glow, and a white sheen would flatten it into grey.
    sheenOpacity: 0.92,
    barOpacity: [1, 0.62, 0.38],
    barTrack: "#dbd4f0",
    // Ink for mono provider logos (Cursor / Copilot / Hermes), which ship
    // without a fill so they can read on either background.
    logoInk: "#16161f",
    // The bolt itself, and the app-icon tile behind it. The tile gradient is
    // inlined in brandMarkSvg() straight from the shipped icon SVG rather than
    // held here, so it stays a verbatim copy of the source. Light theme keeps
    // the same dark tile rather than inverting — an inverted bolt reads as a
    // different logo.
    boltInk: "#ffffff",
  },
  dark: {
    bgTop: "#0c0c13",
    bgBottom: "#050507",
    cardBorder: "#1b1b26",
    fg: "#ffffff",
    secondary: "#e5e5e5",
    muted: "#8b8b9e",
    faint: "#5f5f72",
    // Provider percentages: brighter than the panel heading (muted) but a step
    // below the provider labels (secondary) — increased whiteness without going
    // full white, so the column still yields to the names it annotates.
    pctInk: "#b9b9ca",
    accent: "#8a7aff",
    accentSoft: "#b8b3ff",
    divider: "#1c1c27",
    glowOpacity: 0.26,
    // No white sheen here: the dark card reads as deep space lit from within
    // by the accent glow, and a specular highlight would flatten it to grey.
    sheenOpacity: 0,
    barOpacity: [1, 0.66, 0.4],
    barTrack: "#1b1b26",
    logoInk: "#e6e3f5",
    // Same dark app-icon tile as light theme. On the dark card the near-black top
    // blends into the background and the tile reads through its lit lower edge,
    // which is how the shipped icon sits on a dark surface anyway.
    boltInk: "#ffffff",
  },
};

// Provider segment hues for the provider panel, taken from the dashboard's own
// chart palette (PROVIDER_COLORS in UsageOverview.jsx) so a provider wears the
// same color in the badge as it does in the app.
const PROVIDER_HUES: Record<string, string> = {
  Claude: "#d97757",
  Codex: "#3b82f6",
  Gemini: "#2196f3",
  Cursor: "#14b8a6",
  Copilot: "#a78bfa",
  Hermes: "#f59e0b",
};

// The official TokenTracker bolt, copied verbatim from the shipped app icon
// (TokenTrackerBar/AppIcon.icon). Its own 200-unit viewBox is retained, so the
// mark can be placed with plain width/height and the geometry stays identical to
// the source — no rescaling, no re-fitting.
//
// Inlined rather than redrawn from a PNG, so the badge's mark stays
// pixel-identical to the app icon, macOS icon and tray icon. Do NOT "sync" it
// from TokenTrackerBar/AppIcon.icon/Assets/02-bolt.svg: that is a different
// bolt, not a rescale of this one.
const TT_BOLT_VIEWBOX = "0 0 200 200";
const TT_BOLT_PATH =
  "M92.47 45.94A4.2 4.2 0 0 1 100.00 48.50L100.00 85.00L142.18 85.00A9 9 0 0 1 149.32 99.47" +
  "L107.53 154.06A4.2 4.2 0 0 1 100.00 151.50L100.00 115.00L57.82 115.00A9 9 0 0 1 50.68 100.53Z";

// The bolt's own bbox inside that viewBox is x 50.68..149.32 (98.64 wide),
// y 44.30..155.70 (111.40 tall), centred exactly on (100, 100) — i.e. it fills
// only 49.3% x 55.7% of the symbol. See TT_BOLT_FILL_RATIO and BOLT_TARGET_*,
// which size the bolt against the tile rather than against this padded box.

// --- BEGIN GENERATED: badge provider logos ---
// Generated by scripts/build-badge-logos.mjs from
// dashboard/public/brand-logos/. Do not edit by hand — re-run the script.
//
// `mono` logos ship without a fill so they inherit the theme ink set at the
// <use> site (see providerLogoUse); brand-color logos keep their own fills.
// Only the providers a card actually renders get a <symbol>, so a user on
// three providers doesn't ship the other three logos' path data.
function badgeLogoSymbols(labels: string[]): string {
  return labels
    .filter((label) => BADGE_PROVIDER_LOGOS[label])
    .map((label) => {
      const { viewBox, markup } = BADGE_PROVIDER_LOGOS[label];
      return `<symbol id="bpl-${label}" viewBox="${viewBox}">${markup}</symbol>`;
    })
    .join("");
}

