const FONT_STACK =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";
const MONO_STACK =
  "ui-monospace, 'JetBrains Mono', 'Cascadia Code', Consolas, 'Courier New', monospace";

function svgResponse(svg: string, status = 200, cacheSeconds = 60): Response {
  return new Response(svg, {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "image/svg+xml; charset=utf-8",
      "Cache-Control": `public, max-age=${cacheSeconds}, s-maxage=${cacheSeconds}`,
    },
  });
}

function escapeXml(s: string): string {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function isUuid(s: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
}

function compactNumber(n: number): string {
  if (!isFinite(n)) return "0";
  const abs = Math.abs(n);
  if (abs >= 1e12) return (n / 1e12).toFixed(2).replace(/\.?0+$/, "") + "T";
  if (abs >= 1e9) return (n / 1e9).toFixed(2).replace(/\.?0+$/, "") + "B";
  if (abs >= 1e6) return (n / 1e6).toFixed(2).replace(/\.?0+$/, "") + "M";
  if (abs >= 1e3) return (n / 1e3).toFixed(2).replace(/\.?0+$/, "") + "K";
  return String(Math.round(n));
}

/**
 * Formats a dollar figure for the stat row. Above a million it switches to the
 * same S/M/B/T ladder compactNumber() uses, which bounds the printed width:
 * `toLocaleString` on an unbounded cost kept adding digits
 * ("$1,000,000,000,000,000"), and no amount of shrinking the row could fit that.
 */
function formatCost(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1e6) {
    const units = [
      [1e12, "T"], [1e9, "B"], [1e6, "M"],
    ] as const;
    for (const [scale, suffix] of units) {
      if (abs >= scale) return "$" + (n / scale).toFixed(2).replace(/\.?0+$/, "") + suffix;
    }
  }
  if (n >= 1000) return "$" + Math.round(n).toLocaleString("en-US");
  if (n >= 100) return "$" + n.toFixed(0);
  return "$" + n.toFixed(2);
}


function placeholderSvg(message: string, theme: "light" | "dark"): string {
  const p = PALETTE[theme];
  return `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="180" role="img" aria-label="${escapeXml(message)}">
    <title>${escapeXml(message)}</title>
    <rect width="600" height="180" rx="16" fill="${p.bgBottom}" stroke="${p.cardBorder}" />
    <text x="300" y="97" text-anchor="middle" font-family="${FONT_STACK}" font-size="15" font-weight="600" fill="${p.fg}">${escapeXml(message)}</text>
  </svg>`;
}

// The hero card gives the name x=88..~420 before the provider panel starts, so
// ~26 glyphs is safe at 21px/700. The old card had no clamp and a long name
// simply ran off the canvas (and under the URL text); truncate instead.
function truncateName(name: string, max = 26): string {
  return name.length > max ? name.slice(0, max - 1).trimEnd() + "…" : name;
}

interface ProviderShare {
  label: string;
  val: number;
  pct: number;
  color: string;
}

// Provider shares, sorted so the panel can take the top three. Percentages are
// of the providers listed here, not of total_tokens -- which covers more.
function providerShares(row: SnapshotRow): ProviderShare[] {
  const providers = [
    { label: "Claude", val: Number(row.claude_tokens ?? 0) },
    { label: "Codex", val: Number(row.gpt_tokens ?? 0) },
    { label: "Gemini", val: Number(row.gemini_tokens ?? 0) },
    { label: "Cursor", val: Number(row.cursor_tokens ?? 0) },
    { label: "Copilot", val: Number(row.copilot_tokens ?? 0) },
    { label: "Hermes", val: Number(row.hermes_tokens ?? 0) },
  ];
  const total = providers.reduce((s, x) => s + x.val, 0);
  return providers
    .filter((x) => x.val > 0)
    .sort((a, b) => b.val - a.val)
    .map((x, i) => ({
      ...x,
      pct: total > 0 ? (x.val / total) * 100 : 0,
      // Positional fallback for a provider with no color entry above, matching
      // getProviderColor's scheme in the dashboard.
      color: PROVIDER_HUES[x.label] ?? `hsl(${150 + i * 40}, 60%, 45%)`,
    }));
}

interface SnapshotRow {
  user_id: string;
  display_name: string | null;
  rank: number | null;
  total_tokens: number | null;
  estimated_cost_usd: number | null;
  gpt_tokens: number | null;
  claude_tokens: number | null;
  gemini_tokens: number | null;
  cursor_tokens: number | null;
  hermes_tokens: number | null;
  copilot_tokens: number | null;
  is_public: boolean | null;
  generated_at: string;
}

// deno-lint-ignore no-explicit-any
async function windowBounds(client: any, period: string): Promise<{ from_day: string; to_day: string }> {
  const now = new Date();
  if (period === "week") {
    const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
    d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7)) /* ISO Mon-start, matches leaderboard-refresh+dashboard */;
    const from_day = d.toISOString().slice(0, 10);
    d.setUTCDate(d.getUTCDate() + 6);
    return { from_day, to_day: d.toISOString().slice(0, 10) };
  }
  if (period === "month") {
    const from_day = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, "0")}-01`;
    const to_day = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 0))
      .toISOString()
      .slice(0, 10);
    return { from_day, to_day };
  }
  const { data: latest } = await client.database
    .from("tokentracker_leaderboard_snapshots")
    .select("from_day, to_day")
    .eq("period", "total")
    .order("to_day", { ascending: false })
    .limit(1)
    .maybeSingle();
  const row = latest as { from_day?: string; to_day?: string } | null;
  return {
    from_day: (row?.from_day ?? "2024-01-01").slice(0, 10),
    to_day: (row?.to_day ?? now.toISOString()).slice(0, 10),
  };
}

// Sky gradient, a lit sheen and an accent glow, all clipped to the rounded card.
//
// No texture: no specks, grid or noise. A starfield, sweeping glint orbs and
// per-star twinkling were each tried and removed — anything in the background
// competes with the figures, which are the badge's subject, and a mark small
// enough not to compete is not worth its bytes. The lit gradient alone reads as
// depth. Only the figures and the provider bars animate; a test enforces that.
function backdropSvg(theme: "light" | "dark", idSuffix: string): string {
  const p = PALETTE[theme];
  const sky = `bd-sky-${idSuffix}`;
  const glow = `bd-glow-${idSuffix}`;
  const sheen = `bd-sheen-${idSuffix}`;
  const clip = `bd-clip-${idSuffix}`;
  return `<defs>
    <linearGradient id="${sky}" x1="0" y1="0" x2="0.35" y2="1">
      <stop offset="0" stop-color="${p.bgTop}"/>
      <stop offset="1" stop-color="${p.bgBottom}"/>
    </linearGradient>
    <radialGradient id="${glow}" cx="0.78" cy="0.02" r="0.72">
      <stop offset="0" stop-color="${p.accent}" stop-opacity="${p.glowOpacity}"/>
      <stop offset="0.55" stop-color="${p.accent}" stop-opacity="${p.glowOpacity * 0.28}"/>
      <stop offset="1" stop-color="${p.accent}" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="${sheen}" cx="0.06" cy="0.02" r="0.85">
      <stop offset="0" stop-color="#ffffff" stop-opacity="${p.sheenOpacity}"/>
      <stop offset="0.4" stop-color="#ffffff" stop-opacity="${p.sheenOpacity * 0.45}"/>
      <stop offset="1" stop-color="#ffffff" stop-opacity="0"/>
    </radialGradient>
    <clipPath id="${clip}"><rect width="600" height="180" rx="16"/></clipPath>
  </defs>
  <rect width="600" height="180" rx="16" fill="url(#${sky})"/>
  <g clip-path="url(#${clip})">
    <rect width="600" height="180" fill="url(#${sheen})"/>
    <rect width="600" height="180" fill="url(#${glow})"/>
  </g>
  <rect x="0.5" y="0.5" width="599" height="179" rx="16" fill="none" stroke="${p.cardBorder}"/>`;
}

/**
 * The TokenTracker bolt as a reusable symbol. Emitted once per document and
 * placed with `<use>`, the same pattern the provider logos use.
 *
 * The path carries NO fill attribute: `currentColor` (what the source asset
 * uses) resolves against the *inherited text color*, not the `<use>` element's
 * fill, so it would render black on the light theme regardless of what the
 * caller asked for. Omitting the attribute lets the `<use>` site's fill inherit
 * down as the initial value, which is the same trick the mono provider logos
 * use.
 */
function boltSymbol(): string {
  return `<symbol id="tt-bolt" viewBox="${TT_BOLT_VIEWBOX}"><path d="${TT_BOLT_PATH}"/></symbol>`;
}

/**
 * The bolt inside a rounded tile — the shape of the shipped app icon, so the
 * badge reads as the app at a glance instead of a stray lightning glyph.
 *
 * Sized at 51% x 54% of the tile, the app icon's own proportion (0.94:1), which
 * keeps it inside the tile with margin while still reading at 22px. That is the
 * PAINTED fill, not the `<use>` box: `tt-bolt` carries the source's own
 * `0 0 200 200` viewBox which the bolt fills only partway, so a `<use>` sized to
 * 51% of the tile would paint it at ~25%. The box is divided by
 * TT_BOLT_FILL_RATIO to undo that padding.
 */
const BOLT_TARGET_W = 0.51;
const BOLT_TARGET_H = 0.54;
// Uniform multiplier on top of the target — the single knob for growing or
// shrinking the mark without touching its shape.
const BOLT_SCALE = 1;
// When true, honour the source's own 0.885:1 painted ratio (49.3% x 55.7%) and
// ignore the per-axis targets.
const PRESERVE_ASPECT = false;

// The bolt's PAINTED bbox inside its 200-unit viewBox: x 50.68..149.32 (98.64
// wide), y 44.30..155.70 (111.40 tall), centred on (100, 100). The vertical
// extent comes from flattening the corner arcs, which bulge past their on-curve
// endpoints — an endpoint-only scan underestimates the height by ~3 units.
const TT_BOLT_FILL_RATIO = { w: 98.64 / 200, h: 111.4 / 200 };

function brandMarkSvg(cx: number, cy: number, size: number, p: typeof PALETTE.dark): string {
  const tile = `tt-tile-${size}`;
  // Painted width/height we want, as a fraction of the tile.
  const fillW = PRESERVE_ASPECT ? TT_BOLT_FILL_RATIO.w * BOLT_SCALE : BOLT_TARGET_W * BOLT_SCALE;
  const fillH = PRESERVE_ASPECT ? TT_BOLT_FILL_RATIO.h * BOLT_SCALE : BOLT_TARGET_H * BOLT_SCALE;
  // ...converted to a <use> box, undoing the viewBox padding. Kept numeric so
  // the arithmetic below type-checks; toFixed(2) happens at interpolation, which
  // is where the rounding the emitted SVG has always had actually belongs.
  const useW = size * (fillW / TT_BOLT_FILL_RATIO.w);
  const useH = size * (fillH / TT_BOLT_FILL_RATIO.h);
  // Icon Composer renders AppIcon.icon with the continuous ("squircle") corner,
  // not a circular one. SVG only has `rx`/`ry`, so the tile uses a circular
  // radius sized to sit close to it: ~22% of the tile matches the shipped icon
  // closely at badge scale, where the corner spans ~5px and the difference is
  // sub-pixel. A true superellipse path would cost more bytes than it is worth
  // for a 22px mark.
  const radius = (size * 0.22).toFixed(2);
  const x = (cx - size / 2).toFixed(2);
  const y = (cy - size / 2).toFixed(2);
  return `<defs>
    <!-- The app icon's own background gradient: 90deg (x1/y1 -> x2/y2 vertical),
         ten stops, near-black through the top third then ramping to graphite.
         Sampled verbatim from the shipped icon;
         a 2- or 3-stop approximation loses the long dark dwell at the top. -->
    <linearGradient id="${tile}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#010101"/>
      <stop offset="0.2" stop-color="#050505"/>
      <stop offset="0.3" stop-color="#0d0d0d"/>
      <stop offset="0.4" stop-color="#181818"/>
      <stop offset="0.5" stop-color="#252525"/>
      <stop offset="0.6" stop-color="#323232"/>
      <stop offset="0.7" stop-color="#414141"/>
      <stop offset="0.8" stop-color="#505050"/>
      <stop offset="0.9" stop-color="#5f5f5f"/>
      <stop offset="1" stop-color="#707070"/>
    </linearGradient>
  </defs>
  <rect x="${x}" y="${y}" width="${size}" height="${size}" rx="${radius}" fill="url(#${tile})"/>
  <use href="#tt-bolt" x="${(cx - useW / 2).toFixed(2)}" y="${(cy - useH / 2).toFixed(2)}" width="${useW.toFixed(2)}" height="${useH.toFixed(2)}" fill="${p.boltInk}"/>`;
}

/**
 * Places one provider logo. Returns empty markup for a provider with no
 * vendored asset so a missing logo degrades to the bar alone rather than a
 * broken `<use>`.
 *
 * Only mono logos get an explicit fill — theirs was stripped at build time
 * precisely so it inherits from here. Brand-color logos keep their own fills,
 * so setting one would be dead weight that also tints any future flat mark.
 */
function providerLogoUse(label: string, x: number, y: number, size: number, ink: string): string {
  const logo = BADGE_PROVIDER_LOGOS[label];
  if (!logo) return "";
  const fill = logo.mono ? ` fill="${ink}"` : "";
  return `<use href="#bpl-${label}" x="${x}" y="${y}" width="${size}" height="${size}"${fill}/>`;
}

/**
 * The digit-rolling odometer from the dashboard's Counter component, rebuilt as
 * SMIL so it survives GitHub's camo proxy.
 *
 * SMIL specifically: the badge is served as an externally-referenced SVG in a
 * README `<img>`, where browsers disable JavaScript and block external
 * resources — but SMIL and inline CSS `@keyframes` still run, and camo serves
 * SVG through byte-identical, so neither is stripped.
 *
 * Each digit cell stacks all ten glyphs one pitch apart inside a clip, and the
 * strip translates between two offsets — the same shortest-path rule the app
 * uses, where an offset over five steps goes the other way rather than spinning
 * up through 9 to 0 (RollingDigit in ui/components/Counter.jsx, lines 33-34).
 *
 * The easing is a cubic ease-out rather than the app's spring; see
 * ODO_EASE_CUBIC for why.
 */
const ODO_FONT = 30;
// Geometry below is authored at ODO_FONT and scaled by fontSize / ODO_FONT, so
// the 30px TOKENS figure and the 21px COST/RANK figures share one implementation.
const ODO_PITCH = 30.6;   // strip pitch: one glyph row per step
const ODO_ADVANCE = 18;   // tabular digit width
// Space between cells. Was 4, which measured 4.4px of daylight between 21px
// digits — 40% of a digit's own width, enough to read as tracking. At 2 the
// slack is 3.0px (27%), close to what a tabular face sets on its own. The strip
// pitch above is deliberately unchanged: it spaces the stacked rows and must stay
// wider than the ink or a digit would collide with the one it rolls past.
const ODO_GAP = 2;        // space between cells
const ODO_CELL_H = 23;    // clip height; cap height is ~0.72em

/**
 * Each static glyph's cell width as a multiple of ODO_ADVANCE, measured from
 * Inter's hmtx/glyf at 30px. A cell narrower than the glyph's advance pushes its
 * ink into the neighbouring digit: M advances 1.51x a digit, and the flat 0.8
 * slot the suffixes used made "4.12M" read as "4.12 M".
 */
const ODO_STATIC_WIDTH: Record<string, number> = {
  ".": 0.48,
  "#": 1.06,
  "$": 1.07,
  "%": 1.64,
  B: 1.09,
  T: 1.08,
  K: 1.12,
  M: 1.51,
};
// Baseline for a stat figure, by font size. 150 at 30px and 149 at 21px is a
// 1px drop for a 9px size difference — tuned optical alignment, not a formula.
//
// This is a lookup rather than `fontSize === ODO_FONT ? 150 : 149` because that
// identity check fell through to 149 for any other size, sliding the digits out
// of the clip window (which is anchored on the baseline and sized from the font)
// and rendering them sliced, silently.
const STAT_BASELINES: Record<number, number> = {
  [ODO_FONT]: 150,
  21: 149,
};
function statBaseline(fontSize: number): number {
  const known = STAT_BASELINES[fontSize];
  if (known !== undefined) return known;
  // A crowded row shrinks its figures, and rank is unbounded, so sizes below the
  // tuned 21px are reachable. There is deliberately no lower bound: rank has no
  // ceiling, so any floor here would eventually throw on a legitimate row. The
  // clip window scales with the font, so the digits get small, never sliced.
  const sizes = Object.keys(STAT_BASELINES).map(Number).sort((a, b) => a - b);
  const [lo, hi] = sizes;
  if (fontSize > 0 && fontSize <= hi) {
    const f = (fontSize - lo) / (hi - lo);
    return STAT_BASELINES[lo] + f * (STAT_BASELINES[hi] - STAT_BASELINES[lo]);
  }
  throw new Error(
    `statBaseline: fontSize ${fontSize} is outside the renderable range 0..${hi} — ` +
    `the stat figures cannot be laid out at this size.`,
  );
}
// Per-digit delay, as a fraction of the roll.
const ODO_STAGGER = 0.1;
// How long one digit's own sweep takes. Deliberately LONGER than the stagger so
// each digit arrives while its neighbour is still in flight — the app's cadence,
// where one spring drives every digit off a shared value. At 0.24 the roll was
// visibly shorter than the stagger and read as a slot machine counting one digit
// at a time; the nominal sweep is also longer than its visible part, since the
// easing front-loads its travel.
const ODO_SWEEP = 0.6;
// The easing curve. This started as the app's Framer Motion spring (stiffness
// 220, damping 26, mass 0.8), which is the wrong shape for a one-shot settle:
// that spring drives a continuously-updated value so it never has to arrive,
// while the badge must stop at its target. Measured, it is critically damped
// (zeta 0.98) and covers 94.5% of its travel by t=0.3 — all motion over by 58%
// of the window, leaving a dead hold.
//
// 1 - (1 - t)^3. Chosen over softer curves by measuring them: every step softer
// (quartic, quintic, sextic) spreads its motion over a LARGER dead tail, not a
// smaller one, because a higher power front-loads more violently and peaks
// higher. Cubic keeps motion visible to 72% against the spring's 58% and peaks
// gentlest at 2.99x, so nothing jerks on the way in. Reaches exactly 1 at t=1, so
// unlike the spring there is no asymptote to correct for.
const ODO_EASE_CUBIC = (t: number): number => 1 - Math.pow(1 - t, 3);
// The roll runs ~0.9s. The app's spring settles in ~0.23s, which at badge scale
// reads as a snap — the digits land before the eye has picked them up — so the
// clock is stretched, but not far: at 1.8s it read as sluggish. This lands near
// the 750ms the number-flow reference uses for its digit spins.
const ODO_DURATION = 0.9;
// A beat of stillness before anything moves: the card renders, settles, then
// the roll begins. SMIL's begin shifts every timeline by the same amount, so
// the per-digit and per-row stagger baked into keyTimes survives intact. The
// waiting state must read as "at zero" on its own — bar rects already rest at
// width 0, and each digit strip's base transform is authored to the animation's
// first frame so digits show 0 rather than their frozen target.
const ODO_DELAY = 0.75;

/**
 * The eased value at a fraction of the sweep, clamped at both ends so the strip
 * can never pass its target or its start. Closed form, so the decimal cells can
 * sample it thousands of times without the integration table the spring needed.
 */
function springValueAt(f: number): number {
  return ODO_EASE_CUBIC(Math.max(0, Math.min(1, f)));
}

/**
 * The digit a place shows for a given value — Counter.jsx's
 * getValueRoundedToPlace, including its float guard.
 *
 * The guard is not optional. 11.55 / 0.01 is 1154.9999999999998 in IEEE 754, so
 * a bare Math.floor lands on the last digit showing 4, not 5. Counter.jsx has
 * the same normalizeNearInteger step for exactly this reason.
 */
function odoPlaceDigit(value: number, place: number): number {
  const scaled = value / place;
  const nearest = Math.round(scaled);
  const tolerance = 1e-9 * Math.max(1, Math.abs(scaled));
  const guarded = Math.abs(scaled - nearest) < tolerance ? nearest : scaled;
  return ((Math.floor(guarded) % 10) + 10) % 10;
}

/**
 * Rebuilds a formatted number's cell layout from its own characters, so the roll
 * matches whatever formatter produced it — suffix and trailing-zero trimming
 * included. "11.55B" becomes digit(10), digit(1), static("."), digit(0.1),
 * digit(0.01), static("B"). A leading "#" (RANK) joins the layout as a static
 * glyph beside the digits, exactly as COST's "$" does, so the gap after it is a
 * layout constant rather than an accident of whichever font the renderer picks.
 */
function odoCells(display: string): Array<{ kind: "digit"; place: number } | { kind: "static"; ch: string }> {
  const cells: Array<{ kind: "digit"; place: number } | { kind: "static"; ch: string }> = [];
  const chars = Array.from(display);
  const dot = chars.indexOf(".");
  let intDigits = chars.filter((c, i) => /\d/.test(c) && (dot === -1 || i < dot)).length;
  let dec = 0;
  let pastDot = false;
  for (const ch of chars) {
    if (!/\d/.test(ch)) {
      if (ch === ".") pastDot = true;
      cells.push({ kind: "static", ch });
      continue;
    }
    if (!pastDot) {
      cells.push({ kind: "digit", place: Math.pow(10, Math.max(intDigits - 1, 0)) });
      intDigits -= 1;
    } else {
      dec += 1;
      cells.push({ kind: "digit", place: Math.pow(10, -dec) });
    }
  }
  return cells;
}

/**
 * When a provider bar's row starts filling, as a fraction of the roll.
 *
 * The bars follow the numbers: the first row begins with the leading digit, and
 * each later row is offset like the digits, so the panel cascades down in step
 * with the figures above rather than filling all at once.
 */
function barStart(row: number): number {
  return ODO_STAGGER * (row + 1);
}

// Samples across a bar's width animation. SMIL interpolates linearly between
// whatever it is given, so the spring needs enough points to read as a curve.
const BAR_SAMPLES = 24;

/**
 * Lays out one digit's strip and returns its travel.
 *
 * Glyph d sits at `baseline + (d - digit) * pitch`, so the TARGET digit rests on
 * the baseline and digit 0 sits `digit` pitches below it. Translating from
 * `+digit * pitch` down to 0 rolls it from showing 0 to showing the target.
 * Deriving both endpoints from that one relationship avoids sign errors, which
 * are easy here: translating the other way pulls each strip off its target and,
 * for a digit of 5, clean out of the clip window.
 */
function odoStrip(target: number) {
  const digit = odoPlaceDigit(target, 1);
  return {
    digit,
    // Glyph d sits `d - digit` pitches from the baseline, so the strip's
    // translate to bring digit d home is the negation of that distance.
    y: (d: number) => d - digit,
  };
}

/**
 * Renders `display` as an odometer that rolls from 0 to `target` once on load and
 * then freezes there (`fill="freeze"` — it does not loop). `cells` describes each
 * column: a digit with its decimal place, or a static glyph.
 */
function odometerSvg(opts: {
  x: number;
  baseline: number;
  cells: Array<{ kind: "digit"; place: number } | { kind: "static"; ch: string }>;
  target: number;
  fontSize: number;
  weight: number;
  fill: string;
  idSuffix: string;
  // Fraction of the duration the whole figure waits before rolling, so a
  // provider's percent can start counting on the beat its own bar starts
  // filling. The full timeline is mapped into [start, 1] with a leading hold
  // frame, which keeps keyTimes valid (0 -> 1, never backwards).
  start?: number;
}): { svg: string; width: number } {
  const { x, baseline, cells, target, fontSize, weight, fill, idSuffix } = opts;
  // Scale the geometry, which is authored at ODO_FONT, down to this caller's
  // font size so one implementation serves the 30px and 21px stats alike.
  const k = fontSize / ODO_FONT;
  const pitch = ODO_PITCH * k;
  const advance = ODO_ADVANCE * k;
  const gap = ODO_GAP * k;
  const cellH = ODO_CELL_H * k;
  // The delay is no longer a SMIL `begin` offset — it is a HOLD at the start of
  // the animation's own timeline (see keyTimes below). That keeps one thing true
  // in every renderer: the base attributes already hold the final value, so a
  // renderer that ignores SMIL entirely shows the correct card, while an SMIL one
  // still sits at zero for ODO_DELAY and then rolls.
  const duration = ODO_DELAY + ODO_DURATION;
  // Fraction of that total spent holding at zero before the roll begins.
  const holdEnd = ODO_DELAY / duration;
  let cursor = x;
  const parts: string[] = [];
  const clips: string[] = [];

  // Stagger slot, counting only the digits that actually animate. Static glyphs
  // (the "." and the unit suffix) are punctuation, not digits, so they must not
  // consume a slot — keying off the cell index left a double-width gap between
  // the two digits straddling the decimal point, which read as the cascade
  // pausing there instead of continuing through it.
  let digitSlot = 0;
  cells.forEach((cell, i) => {
    if (cell.kind === "static") {
      // A static glyph's cell is sized from the real face via ODO_STATIC_WIDTH,
      // as a multiple of a digit's advance. One flat 0.8 was wrong for every
      // suffix but the narrowest: Inter's M advances 1.51x a tabular digit
      // (27.1px against 18px at 30px), so in a 0.8 cell its ink overhung by
      // 3.7px on each side and crowded the digit in front of it — "4.12M" read
      // as "4.12 M". The cell carries the glyph's advance, not its ink, so the
      // trailing gap after it is one gap rather than a space-width hole.
      const w = advance * (ODO_STATIC_WIDTH[cell.ch] ?? 1);
      parts.push(
        `<text x="${(cursor + w / 2).toFixed(2)}" y="${baseline.toFixed(2)}" text-anchor="middle" font-size="${fontSize}" font-weight="${weight}" fill="${fill}">${escapeXml(cell.ch)}</text>`,
      );
      // The trailing space after a static is a FULL gap, not 40% of one.
      // At 40% the decimal point inherited the digit cells' slack on its
      // trailing side while keeping a narrow cell of its own, which measured
      // 9.65px of daylight between "1" and "." against 2.73px between digits.
      // The eye reads that as a gap in the number rather than as a decimal
      // point, which is the same complaint as loose digit spacing, one column
      // over. The "." carries almost no ink, so it needs no extra clearance —
      // a full gap leaves it optically tight to both neighbours.
      cursor += w + gap;
      // Static glyphs do NOT consume a stagger slot.
      return;
    }
    const slot = digitSlot++;

    // This cell's digit at rest, derived exactly as Counter.jsx does:
    // Math.floor(value / place) % 10. The strip is laid out so that digit sits
    // on the baseline.
    const strip = odoStrip(target / cell.place);
    // Only the rows the roll can reveal are emitted. The clip window hangs 4*k
    // below the baseline while rows sit ODO_PITCH*k apart, and both scale with
    // the font, so the hang stays 0.13 of a pitch at every size: a row above the
    // target can never enter the window. That was 10 rows per cell where the
    // average target needs 6, and the rows were a third of the payload.
    const rows: string[] = [];
    for (let d = 0; d <= strip.digit; d++) {
      rows.push(
        `<text x="${cursor.toFixed(2)}" y="${(baseline + strip.y(d) * pitch).toFixed(2)}">${d}</text>`,
      );
    }
    // Glyph d sits at (d - restDigit) * pitch, so translating by the negation
    // brings whichever digit the value currently reads onto the baseline.
    const placeValue = cell.place;
    const restDigit = strip.digit;
    const frames: string[] = [];
    const times: number[] = [];
    // Samples across the roll, chosen by how far the painted line can stray from
    // the curve between two of them. Worst case (a strip travelling nine pitches):
    // 240 steps -> 0.010px, 60 -> 0.157px, 24 -> 0.96px. 60 keeps it under a
    // sixth of a pixel and cuts the values/keyTimes lists from ~33KB to ~8KB.
    //
    // keySplines + calcMode="spline" would carry the ease in a few keyframes, but
    // the curve below is a polynomial and SMIL's spline is a cubic Bezier, which
    // cannot match it exactly — that would alter the roll's shape.
    const steps = 60;
    // Each digit sweeps ONCE, from showing 0 to its final value: the offset is
    // `restDigit * pitch * (1 - progress)` — bounded by the digit's own value,
    // continuous, with no wrap to jump across.
    //
    // The app's per-frame formula (drive from the digit the value currently
    // reads) cannot work here: the hundredths digit of 11.55 changes 1155 times,
    // and every 9 -> 0 crossing jumps the strip a whole ten pitches. The app
    // hides that in a 60fps blur; baked into SMIL it is a visible 275px
    // teleport. Sweeping once also drops the worst inter-frame step from 3035px
    // to 2px against a 30.6px pitch.
    //
    // Sampling must be dense enough that SMIL's linear interpolation between
    // points never skips a digit: a place whose digit changes `target/place`
    // times over the roll needs at least that many samples, so the decimal cells
    // are sampled far more finely than the leading ones.
    //
    // Every cell sweeps over the same window, delayed by a per-digit slot so the
    // number cascades left to right. The slot is keyed to the DIGIT's position,
    // not its cell index: "." is static, and counting it doubled the gap across
    // the decimal point.
    //
    // The delay is capped so delay + ODO_SWEEP can never exceed 1. Left
    // uncapped, slot 5 onwards started so late that `local` never reached 1
    // before t=1, and fill="freeze" froze the strip PART WAY THROUGH its roll:
    // a $1,234,568 cost left its last two digits at "0 0.60" and "0 6.35"
    // against a 21.4px pitch, visibly half-rolled. It takes a 6th digit to show,
    // so a $100,000+ cost or a #100000+ rank hit it.
    //
    // The cascade is untouched for the digits that fit (a 4-digit figure still
    // cascades over 0 / 0.1 / 0.2 / 0.3). Past the cap the remaining digits
    // start together and finish together, which reads as one wide group rolling
    // rather than as a broken tail.
    const delay = Math.min(ODO_STAGGER * slot, 1 - ODO_SWEEP);
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      // Clamped: a digit whose slot starts late waits at its start offset until
      // its turn comes, then sweeps over ODO_SWEEP of the roll.
      const local = Math.max(0, Math.min(1, (t - delay) / ODO_SWEEP));
      const progress = springValueAt(local);
      const remaining = restDigit * (1 - progress);
      const frame = `0 ${(remaining * pitch).toFixed(2)}`;
      // Collapse CONSECUTIVE duplicates: a run of identical offsets carries no
      // motion, but its first entry must be kept or the strip teleports.
      if (frames[frames.length - 1] !== frame) {
        frames.push(frame);
        times.push(t);
      }
    }
    // keyTimes must accompany values: dropping a duplicate would otherwise let
    // SMIL redistribute the remaining frames evenly across the duration, which
    // would stretch the settled hold into a slow crawl.
    //
    // The last keyTime MUST be exactly 1 — SMIL rejects the whole element if the
    // list does not start at 0 and end at 1, and a rejected animateTransform means
    // the digits never move at all. The dedup above can drop the final sample, so
    // the tail is forced back onto 1 here.
    times[times.length - 1] = 1;
    if (times.length < 2) {
      // A digit already sitting at its target produces a single-frame roll.
      // SMIL requires values and keyTimes to agree in length and keyTimes to
      // run 0 -> 1, so hold the value across the whole window instead.
      times[0] = 0;
      times.push(1);
      frames.push(frames[0]);
    }
    // Roll space [0,1] -> animation space. The animation holds at zero through
    // ODO_DELAY as its first span, then rolls. `start` (a provider percent's own
    // beat) pushes the roll further in, so a strip waiting for its row holds for
    // longer — one hold, not two mechanisms.
    //
    // The flat stretch before the roll is bracketed by two equal values: the dedup
    // above collapses it to one sample, and SMIL interpolates linearly, so the
    // strip would creep toward its target during the wait.
    const start = opts.start ?? 0;
    const rollStart = holdEnd + (1 - holdEnd) * start;
    const at = (t: number) => rollStart + (1 - rollStart) * t;
    const kt: number[] = [0, rollStart];
    const values: string[] = [frames[0], frames[0]];
    if (delay > 0) {
      kt.push(at(delay));
      values.push(frames[0]);
    }
    for (let i = 1; i < times.length; i++) {
      kt.push(at(times[i]));
      values.push(frames[i]);
    }
    const keyTimes = `keyTimes="${kt.map((t) => t.toFixed(4)).join(";")}"`;
    const clipId = `odo-${idSuffix}-${i}`;
    clips.push(
      `<clipPath id="${clipId}"><rect x="${(cursor - 1).toFixed(2)}" y="${(baseline - cellH).toFixed(2)}" width="${(advance + 2 * k).toFixed(2)}" height="${(cellH + 4 * k).toFixed(2)}"/></clipPath>`,
    );
    // The base transform is the strip's FINAL state — the target digit sitting on
    // the baseline — because that is what a renderer with no SMIL support paints:
    // it reads the static attribute and ignores the <animateTransform> entirely.
    // Parked at "0 showing" instead, every such renderer showed 0.00B / $000 /
    // #000 and empty bars forever: resvg, librsvg, ImageMagick, sharp, and every
    // link-preview or OG-image generator that rasterizes rather than animates.
    //
    // The roll is preserved by starting the animation at 0s and holding at zero
    // through ODO_DELAY inside its own timeline (see holdEnd above), so an SMIL
    // renderer still shows zeros first and then rolls.
    const atRest = "translate(0 0.00)";
    // font-size/weight/fill are identical on every glyph of the cell, so they sit
    // on the group and inherit. That was ~70 bytes repeated on each of the 10
    // rows, which was a fifth of the whole payload.
    const ink = `font-size="${fontSize}" font-weight="${weight}" fill="${fill}"`;
    parts.push(
      `<g clip-path="url(#${clipId})" ${ink}><g transform="${atRest}">${rows.join("")}<animateTransform attributeName="transform" type="translate" begin="0s" dur="${duration}s" fill="freeze" values="${values.join(";")}" ${keyTimes}/></g></g>`,
    );
    cursor += advance + gap;
  });

  const defs = clips.length ? `<defs>${clips.join("")}</defs>` : "";
  return {
    svg: `${defs}<g class="tt-odo" style="font-variant-numeric: tabular-nums">${parts.join("")}</g>`,
    // The cursor overshoots by one trailing gap, so trim it: the divider that
    // follows the figure should hang off the last glyph's own right edge, not
    // off the cell padding that exists only to separate digits from each other.
    width: Math.max(0, cursor - x - gap),
  };
}

/**
 * The width a display string occupies, in the same terms odometerSvg() lays it
 * out. Figures vary from 38px to 134px wide, so the layout needs this to place
 * each divider a fixed distance from the figure it follows.
 */
function odoWidth(value: string, fontSize: number): number {
  const unit = fontSize / ODO_FONT;
  const advance = ODO_ADVANCE * unit;
  const gap = ODO_GAP * unit;
  let w = 0;
  for (const ch of value) {
    // Must mirror odometerSvg's cursor EXACTLY, or the dividers that hang off
    // this width drift away from the figures they are meant to follow. "#" used
    // to be special-cased here as a full digit while the renderer gave it 1.06x,
    // which left this 0.8px narrow and pushed RANK under the panel on the widest
    // row — so every static goes through the same table the renderer reads.
    w += (ch >= "0" && ch <= "9" ? advance : advance * (ODO_STATIC_WIDTH[ch] ?? 1)) + gap;
  }
  // The cursor overshoots by one trailing gap; trim it so the measured width is
  // the glyph edge a divider should hang off.
  return Math.max(0, w - gap);
}

function renderProfileCard(opts: {
  row: SnapshotRow;
  theme: "light" | "dark";
  period: string;
}): string {
  const { row, theme, period } = opts;
  const p = PALETTE[theme];
  const displayName = row.display_name || "Anonymous";
  const tokens = compactNumber(Number(row.total_tokens ?? 0));
  const cost = row.estimated_cost_usd == null ? "Partial cost" : formatCost(Number(row.estimated_cost_usd));
  const rank = row.rank ? `#${row.rank}` : "—";
  const periodLabel = period.charAt(0).toUpperCase() + period.slice(1);
  const shares = providerShares(row).slice(0, 3);

  // Stats are bare type on the canvas, separated by hairline dividers rather
  // than boxed in pills — the landing page is mostly flat and lets white type
  // carry the hierarchy, with borders only as structure. Only TOKENS is
  // oversized, so scale alone marks it as the headline number.
  //
  // All three figures get the app's rolling odometer, at two sizes. TOKENS
  // leads because it is the headline; COST and RANK follow at 21px so the row
  // reads as one figure arriving rather than three unrelated counts.
  const stat = (x: number, label: string, value: string, fontSize: number, weight: number, fill: string, animated: number, suffix: string) => {
    // A zero figure has no roll worth showing — every digit would sweep from 0 to
    // 0 and sit still, which is worse than simply drawing the value. Render it
    // as plain type instead.
    if (!(animated > 0)) {
      return `<g>
      <text x="${x}" y="118" font-size="9.5" font-weight="600" letter-spacing="1.8" fill="${p.muted}">${label}</text>
      <text x="${x}" y="${statBaseline(fontSize)}" font-size="${fontSize}" font-weight="${weight}" fill="${fill}">${escapeXml(value)}</text>
    </g>`;
    }
    // The roll happens in the DISPLAY string's units, and the target is read back
    // off that string rather than derived from the raw number: "11.55B" is 11.55,
    // "$1,235" is 1235, "#652" is 652. Scaling the raw value by a suffix factor
    // only approximated that — every digit uses floor(), while compactNumber and
    // formatCost round — so about half of all real values settled one unit low
    // ("11.56B" printing as 11.55B, "$617" as $616). Reading the printed figure
    // settles the odometer on exactly the digits the card shows, and carry cases
    // come for free: "12B" targets 12, not the 11.999 it was rounded from.
    const displayed = Number(value.replace(/[^\d.]/g, ""));
    const baseline = statBaseline(fontSize);
    // RANK's "#" and COST's "$" ride the odometer as leading static cells, so
    // the gap after them is laid out by odometerSvg like any other glyph.
    return `<g>
      <text x="${x}" y="118" font-size="9.5" font-weight="600" letter-spacing="1.8" fill="${p.muted}">${label}</text>
      ${odometerSvg({
        x,
        baseline,
        cells: odoCells(value),
        target: displayed,
        fontSize,
        weight,
        fill,
        idSuffix: suffix,
      }).svg}
    </g>`;
  };

  // Five non-overlapping columns: logo, label, bar, percent. The percent sits
  // AFTER the bar (not before it) so a long provider name can never collide
  // with its own percentage.
  //
  // Each bar grows from nothing on the same spring that drives the numbers, so
  // the whole card resolves together instead of the bars snapping to full width
  // under a still-counting figure. The rows are offset from each other so they
  // also cascade down the list rather than appearing as one block.
  // Provider panel geometry.
  //
  // The panel shares the card's right margin with the brand lockup: the bolt
  // tile is centred at 566 with a halfway size of 22, so its right edge — and
  // every percent's — lands on 577. The percent is right-anchored there, so it
  // grows leftwards and the gap has to be reserved against its widest print,
  // "100%" (~26px): anchoring at the bar end instead of the margin is how a
  // three-digit percentage once ended up on top of the bar.
  //
  // That margin budget is spent on the label column first: the longest provider
  // name ("Hermes", ~33px) plus a small gap decides where the bar starts, and
  // whatever is left becomes the bar — 47px, wide enough that a 14% row still
  // reads as a proportion rather than a tick.
  // Cap height of Inter as a fraction of its font size — the shared conversion
  // between a baseline and the line glyphs start on. Declared here because the
  // provider rows need it to centre the bar and logo against the label.
  const CAP = 0.72;
  const PANEL_X = 438;
  const RIGHT_EDGE = 577; // brand tile's right edge (566 + 22/2) — the card's right margin line
  const ROW_FONT = 10.5;
  const LOGO = 13;
  const BAR_H = 4;
  const BAR_W = 47;
  // Label column: wide enough for the longest provider name, plus a fixed gap
  // before the bar so short and long names leave the bar starting in one place.
  const LABEL_W = 34;
  const LABEL_GAP = 7;
  const barX = PANEL_X + LOGO + 5 + LABEL_W + LABEL_GAP;
  const pctX = RIGHT_EDGE;
  // The odometer right-aligns by cell advance, so the grid's right edge is the
  // right edge of the "%" CELL, not of its ink — and the two are 1.18px apart at
  // this size (Inter's right side bearing). The grid is therefore anchored so
  // that the INK, not the cell, lands on the margin line, exactly as the old
  // static right-anchored text did.
  //
  // Giving "%" its real advance (ODO_STATIC_WIDTH) flipped which side of the ink
  // the cell edge fell on: in the old narrow 0.8 cell the ink overhung by 1.46px
  // and the grid was pulled IN by that much; now the ink sits inside the cell's
  // own right side bearing, so the grid is pushed OUT by the same amount.
  const PCT_BLEED = -1.18;
  const bars = shares.length
    ? shares
        .map((s, i) => {
          const y = 124 + i * 16;
          const pct = Math.round(s.pct);
          const full = (s.pct / 100) * BAR_W;
          // Grow on the same easing the digits use, so the bar eases in rather than
          // running linearly. Keypoints are sampled evenly across the row's own
          // window and mapped back onto the shared timeline.
          const start = barStart(i);
          const stop = Math.min(1, start + ODO_SWEEP);
          // Same two-phase timeline as the digits: hold at zero until this row's
          // beat, then grow to full width. keyTimes must run 0 -> 1 or SMIL
          // rejects the element outright.
          //
          // The bar's base width is its FINAL value for the same reason the digit
          // strips' base transform is the final digit: a renderer without SMIL
          // reads the static attribute, and a base of 0 meant every provider row
          // rendered as an empty track there.
          const barDuration = ODO_DELAY + ODO_DURATION;
          const barHoldEnd = ODO_DELAY / barDuration;
          const pts: string[] = ["0", "0"];
          const keys: number[] = [0, barHoldEnd];
          for (let s = 0; s <= BAR_SAMPLES; s++) {
            const local = s / BAR_SAMPLES;
            pts.push((full * springValueAt(local)).toFixed(2));
            keys.push(barHoldEnd + (1 - barHoldEnd) * (start + (stop - start) * local));
          }
          pts.push(full.toFixed(2));
          keys.push(1);
          // Provider row geometry. Every element is placed off the label's CAP LINE
          // rather than off its baseline, so the bar and the logo sit optically
          // centred with the text instead of riding above it — the bar was
          // 1.22px high at baseline-7. Cap height is ~0.72em, so the optical
          // centre of the text is CAP_FONT*CAP/2 above the baseline, and the
          // bar's top follows from its own height.
          const capMid = ROW_FONT * CAP / 2;
          const barY = (y - capMid - BAR_H / 2).toFixed(2);
          // Number(), not a bare toFixed(): providerLogoUse takes a number, and
          // rounding here rather than at interpolation keeps the emitted
          // coordinates byte-identical to what the string form produced.
          const logoY = Number((y - capMid - LOGO / 2).toFixed(2));
          // The percent counts up on the same odometer as the stat figures:
          // its digits roll from 0 to the share (no slide), and it starts on
          // the beat its own bar starts filling (barStart). The cell grid is
          // measured with a throwaway layout, then re-rendered so the grid's
          // right edge — the tabular column right every row shares — lands on
          // the margin line rather than the anchor point.
          const pctCells = odoCells(`${pct}%`);
          const pctOpts = {
            baseline: y,
            cells: pctCells,
            target: pct,
            fontSize: ROW_FONT,
            weight: 400,
            fill: p.pctInk,
            idSuffix: `p${i}`,
            start: barStart(i),
          };
          const pctGrid = odometerSvg({ ...pctOpts, x: 0 }).width;
          const pctBody = odometerSvg({ ...pctOpts, x: pctX - PCT_BLEED - pctGrid }).svg;
          return `${providerLogoUse(s.label, PANEL_X, logoY, LOGO, p.logoInk)}
      <text x="${PANEL_X + LOGO + 5}" y="${y}" font-size="${ROW_FONT}" fill="${p.secondary}">${escapeXml(s.label)}</text>
      <rect x="${barX}" y="${barY}" width="${BAR_W}" height="${BAR_H}" rx="${BAR_H / 2}" fill="${p.barTrack}"/>
      <rect x="${barX}" y="${barY}" width="${full.toFixed(2)}" height="${BAR_H}" rx="${BAR_H / 2}" fill="${s.color}" fill-opacity="${p.barOpacity[i]}"><animate attributeName="width" begin="0s" dur="${barDuration}s" fill="freeze" values="${pts.join(";")}" keyTimes="${keys.map((t) => t.toFixed(4)).join(";")}" calcMode="linear"/></rect>
      ${pctBody}`;
        })
        .join("\n    ")
    : `<text x="${PANEL_X}" y="126" font-size="${ROW_FONT}" fill="${p.faint}">No provider data yet</text>`;

  // Identity row geometry. Neither card draws an avatar any more.
  const NAME_FONT = 21;
  const NAME_BASELINE = 51;
  const SUBTITLE_FONT = 11.5;
  const SUBTITLE_BASELINE = 70;
  // The name leads on the same 28px gutter the stat row below uses.
  const TEXT_X = 28;

  const BRAND_FONT = 9;
  const BRAND_TILE = 22;
  const BRAND_GAP = 12.5; // baseline to baseline between the two lockup lines
  const nameCapTop = NAME_BASELINE - NAME_FONT * CAP;

  // The wordmark hangs off the NAME'S CAP LINE rather than the row centre:
  // centring a 9px line against a 21px name put its cap top ~10px below the
  // name's, so the two read as starting at different levels.
  const brandBaseline = nameCapTop + BRAND_FONT * CAP;
  const brandSubBaseline = brandBaseline + BRAND_GAP;
  // The tile centres on the lockup's own two-line block, which is what keeps it
  // attached to the text rather than to the row.
  const brandBlockCentre = (nameCapTop + brandSubBaseline) / 2;

  // Stat row layout. The dividers sit a fixed gap BEYOND their own figure rather
  // than at a hardcoded x. They used to be pinned at 216 and 334, sized for the
  // widest printable value ("999.99T" needs 134px); anything narrower left the
  // reserved space as a hole — "11.55B" needs 90px, so 78px of nothing sat
  // between the "B" and the divider. Figures range from 38px ("1M") to 134px, so
  // no fixed x serves all of them.
  //
  // Packing the columns tight would just move the hole to the far end, so the
  // gaps share whatever room is left between the gutter and the panel.
  //
  // The widest printable row needs ~395px of figures in a 410px span, which leaves
  // too little for two gaps AND a margin — letting the gaps go to zero left RANK
  // touching the panel. So the figures shrink to make room. Scale only ever goes
  // DOWN, so an ordinary row keeps the 30px/21px hierarchy and the tuned baselines.
  const MIN_GAP = 8;          // the row may compress its gaps to this, not below
  const PANEL_CLEARANCE = 8; // daylight the row must leave before the panel
  const SMALL = 21;          // the COST/RANK size; TOKENS is ODO_FONT
  // A digit strip's clip window starts 1px left of its cell and is 2*k wider, so
  // it overhangs the cell by (2*k - 1) on the right. The window is what confines
  // the digits, so it is what must stay clear of the panel — not just the cell.
  const clipOverhang = 2 * (SMALL / ODO_FONT) - 1;
  const widest = odoWidth(tokens, ODO_FONT) + odoWidth(cost, SMALL) + odoWidth(rank, SMALL);
  const room = PANEL_X - TEXT_X - clipOverhang - PANEL_CLEARANCE - MIN_GAP * 2;
  const scale = widest <= room ? 1 : room / widest;
  const smallFont = SMALL * scale;
  const tokFont = ODO_FONT * scale;
  const tokW = odoWidth(tokens, tokFont);
  const costW = odoWidth(cost, smallFont);
  const rankW = odoWidth(rank, smallFont);
  const slack = PANEL_X - TEXT_X - clipOverhang - PANEL_CLEARANCE - tokW - costW - rankW;
  // Three gaps' worth of slack, so a narrow row spreads its figures out instead of
  // huddling at the gutter and leaving a hole before the panel. The floor is what
  // a crowded row falls back to; it is never allowed to squeeze the row under the
  // panel, because the figures have already shrunk to make room for MIN_GAP.
  const colGap = Math.max(MIN_GAP, slack / 3);
  const costX = TEXT_X + tokW + colGap;
  const rankX = costX + costW + colGap;
  const div1 = costX - colGap / 2;
  const div2 = rankX - colGap / 2;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="180" viewBox="0 0 600 180" role="img" aria-label="${escapeXml(displayName)} on TokenTracker">
  <title>${escapeXml(displayName)} — ${tokens} tokens, ${cost}, rank ${rank}</title>
  ${badgeLogoSymbols(shares.map((s) => s.label))}
  ${boltSymbol()}
  ${backdropSvg(theme, "hero")}
  <g font-family="${FONT_STACK}">
    <text x="${TEXT_X}" y="${NAME_BASELINE}" font-size="${NAME_FONT}" font-weight="700" letter-spacing="-0.4" fill="${p.fg}">${escapeXml(truncateName(displayName))}</text>
    <text x="${TEXT_X}" y="${SUBTITLE_BASELINE}" font-size="${SUBTITLE_FONT}" fill="${p.muted}">${escapeXml(periodLabel)} usage</text>

    ${brandMarkSvg(566, brandBlockCentre, BRAND_TILE, p)}
    <text x="550" y="${brandBaseline.toFixed(2)}" font-size="${BRAND_FONT}" font-weight="600" letter-spacing="2.2" fill="${p.accent}" text-anchor="end">TOKENTRACKER</text>
    <text x="550" y="${brandSubBaseline.toFixed(2)}" font-size="${BRAND_FONT}" fill="${p.faint}" text-anchor="end">tokentracker.cc</text>

    ${stat(TEXT_X, "TOKENS", tokens, tokFont, 700, p.fg, Number(row.total_tokens ?? 0), "tok")}
    <line x1="${div1.toFixed(2)}" y1="106" x2="${div1.toFixed(2)}" y2="152" stroke="${p.divider}"/>
    ${stat(costX, "COST", cost, smallFont, 600, p.fg, Number(row.estimated_cost_usd ?? 0), "cost")}
    <line x1="${div2.toFixed(2)}" y1="106" x2="${div2.toFixed(2)}" y2="152" stroke="${p.divider}"/>
    ${stat(rankX, "RANK", rank, smallFont, 600, p.accent, row.rank ?? 0, "rank")}

    <text x="${PANEL_X}" y="104" font-size="9.5" font-weight="600" letter-spacing="1.8" fill="${p.muted}">TOP PROVIDERS</text>
    ${bars}
  </g>
</svg>`;
}

export default async function (req: Request): Promise<Response> {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders });
  if (req.method !== "GET") return svgResponse(placeholderSvg("method not allowed", "light"), 405, 0);

  const url = new URL(req.url);
  const userId = (url.searchParams.get("user_id") || "").trim().toLowerCase();
  const theme = (url.searchParams.get("theme") || "light").toLowerCase() === "dark" ? "dark" : "light";
  const period = (url.searchParams.get("period") || "total").toLowerCase();

  if (!userId || !isUuid(userId)) {
    return svgResponse(placeholderSvg("bad user_id", theme), 400, 0);
  }
  if (BLOCKED_LEADERBOARD_USER_IDS.has(userId)) {
    return svgResponse(placeholderSvg("not found", theme), 404, 0);
  }
  if (!["week", "month", "total"].includes(period)) {
    return svgResponse(placeholderSvg("bad period", theme), 400, 0);
  }

  const serviceRoleKey = Deno.env.get("INSFORGE_SERVICE_ROLE_KEY");
  const anonKey = Deno.env.get("INSFORGE_ANON_KEY") ?? Deno.env.get("ANON_KEY");
  const baseUrl = Deno.env.get("INSFORGE_BASE_URL");
  if (!baseUrl) return svgResponse(placeholderSvg("misconfigured", theme), 500, 0);

  const client = createClient({
    baseUrl,
    edgeFunctionToken: serviceRoleKey,
    anonKey: anonKey ?? undefined,
    isServerMode: true,
  });

  let from_day: string;
  let to_day: string;
  try {
    const bounds = await windowBounds(client, period);
    from_day = bounds.from_day;
    to_day = bounds.to_day;
  } catch {
    return svgResponse(placeholderSvg("lookup failed", theme), 502, 0);
  }

  const { data, error } = await client.database
    .from("tokentracker_leaderboard_snapshots")
    .select(
      "user_id, display_name, rank, total_tokens, estimated_cost_usd, gpt_tokens, claude_tokens, gemini_tokens, cursor_tokens, hermes_tokens, copilot_tokens, is_public, generated_at",
    )
    .eq("user_id", userId)
    .eq("period", period)
    .eq("from_day", from_day)
    .eq("to_day", to_day)
    .order("generated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) return svgResponse(placeholderSvg("db error", theme), 502, 0);
  const row = data as SnapshotRow | null;
  if (!row) return svgResponse(placeholderSvg("not found", theme), 404, 0);
  if (row.is_public === false) return svgResponse(placeholderSvg("profile is private", theme), 403, 0);

  return svgResponse(renderProfileCard({ row, theme, period }), 200, 60);
}
